user_prompt:
method rolling_max(numbers: seq<int>) returns (result: seq<int>)
    requires |numbers| > 0 // The input list must be non-empty
    ensures |result| == |numbers| // The output list has the same length as the input list
    ensures forall i :: 0 <= i < |result| ==> result[i] == Max(numbers[0..i+1]) // Each element in result is the max of the prefix of numbers
{
    var maxSoFar := numbers[0];
    var res := new int[|numbers|];

    res[0] := maxSoFar;

    // Iterate through the rest of the numbers
    var i := 1;
    while i < |numbers|
        invariant 0 <= i <= |numbers| // i is within the bounds of the numbers array
        invariant |res| == |numbers| // res has the same length as numbers
        invariant forall j :: 0 <= j < i ==> res[j] == Max(numbers[0..j+1]) // All previous values in res are correct
    {
        maxSoFar := if numbers[i] > maxSoFar then numbers[i] else maxSoFar;
        res[i] := maxSoFar;
        i := i + 1;
    }

    result := res; // Assign the result to the output variable
}

problem_data.canonical_solution:
running_max = None
result = []

for n in numbers:
    if running_max is None:
        running_max = n
    else:
        running_max = max(running_max, n)

    result.append(running_max)

return result

